solution.TextTable.java:
import java.util.*;

public final class TextTable {
    private static boolean isNumber(String s) {
        try {
            Double.parseDouble(s);
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    public static String render(List<String[]> rows) {
        if (rows.isEmpty()) return "";
        int cols = rows.stream().mapToInt(r -> r.length).max().orElse(0);
        int[] width = new int[cols];
        for (String[] row : rows)
            for (int c = 0; c < row.length; c++) width[c] = Math.max(width[c], row[c].length());
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows.size(); r++) {
            String[] row = rows.get(r);
            StringBuilder line = new StringBuilder();
            for (int c = 0; c < cols; c++) {
                String cell = c < row.length ? row[c] : "";
                if (c > 0) line.append("  ");
                boolean right = r > 0 && isNumber(cell);
                line.append(String.format(right ? "%" + width[c] + "s" : "%-" + width[c] + "s", cell));
            }
            sb.append(line.toString().stripTrailing()).append('\n');
            if (r == 0) {
                int total = Arrays.stream(width).sum() + 2 * (cols - 1);
                sb.append("-".repeat(total)).append('\n');
            }
        }
        return sb.toString();
    }
}

unitTests:
test("the example", () -> {
    String out = TextTable.render(List.of(
            new String[] {"name", "qty", "price"},
            new String[] {"tea", "3", "2.50"},
            new String[] {"coffee", "12", "6.00"}));
    checkEq(out, "name    qty  price\n------------------\ntea       3   2.50\ncoffee   12   6.00\n");
});

test("text columns stay left", () -> {
    String out = TextTable.render(List.of(new String[] {"a", "b"}, new String[] {"xyz", "q"}));
    checkEq(out, "a    b\n------\nxyz  q\n");
});

test("nothing", () -> {
    checkEq(TextTable.render(List.of()), "");
});

